"stn2d9": "スティックがどこまで、どれだけ鋭く効くか。チューンではなく、あなたの設定です。アクロのプロポはこのカーブで飛び、キーボードのレースはアングルで始まります。ラン中に変えても、クアッドはその場のまま、時計も止まりません。",
"1m2xvti": "フライトモード",
"xjyq13": "アクロ：スティックは回転速度、手を離すと姿勢を保ちます。アングル：スティックは傾き（Betaflightの上限60度まで）、手を離すと水平に戻ります。このレースはキーボードで飛び、キーボードは独自の設定を持っています（クアッドの「キーボードレース」）。この行はその設定を変えます。飛行中のMでも切り替わります。",
"1r5ubv6": "アクロ：スティックは回転速度、手を離すと姿勢を保ちます。アングル：スティックは傾き（Betaflightの上限60度まで）、手を離すと水平に戻り、ヨーは回転速度のままです。フリップとロールにはアクロが必要です。飛行中のMでも切り替わり、そのまま保存されます。",
