"wyh1np": "クアッドの重さの感じ方。右は重く：スロットルを切ると落ち、ジャンプの頂点で止まらなくなります。左は軽く、ふわりと浮きます。{0}が出荷時のクアッドです。ラップ中に変えるとそのラップは無効になり、{1}以外で飛んだラップは、名前の横に重さを付けて公開ボードに載ります。",
"1ayl725": "エアグリップ",
"6bttpz": "空気がクアッドをどれだけ引き止めるか、つまりスティック中立でどこまで滑るか。左は惰性で進み続けて速く、右は空気がつかんで早く止まり、最高速も下がります。{0}が出荷時のクアッドで、パイロットから届いたチューンをもとに決めています。ラップ中に変えるとそのラップは無効になり、{1}以外で飛んだラップは「Tuned」タグ付きで公開ボードに載ります。",
"ior56v": "モーターパワー",
"1x4irmq": "モーターが1ボルトあたりに出す回転、つまりKV。左はやさしく：パンチが穏やかで最高速も低め。右は力強く、そのぶんバッテリーの電圧降下が大きくなり、ホバー位置はスティックの低い側へ移ります。{0}が出荷時のクアッドで、パイロットから届いたチューンをもとに決めています。ラップ中に変えるとそのラップは無効になり、{1}以外で飛んだラップは「Tuned」タグ付きで公開ボードに載ります。",
"1bsvonq": "初期設定はオフ。オンにすると、クアッドが地面にいる間、スティックの間に重さと並んで{0}が出ます。自分のスライダーで飛んだフライトの最後に、ストックのクアッドより良かったかを聞きます。「はい」と答えないかぎり何も送信されません。オフでは、スライダーがどうなっていてもクアッドは出荷時のまま飛びます。ラップ中に切り替えて飛んでいるクアッドが変わると、そのラップは無効になります。",
