"1siorg1": "自分のスライダーで飛んだフライトが終わったら、ストックより良かったかを聞きます。いつでも「いいえ」と答えられ、「はい」がなければ何も送信されません。オフにすると聞かれません。スライダーはそのまま使えます。",
