"1x4knm": "正直なひとことは、どんなテレメトリーよりもチューン作業の助けになります。必要なのは最初の行だけ。あなたのチューン、PID調整、レートも答えと一緒に届くので、感覚の裏にある数字も伝わります。飛んでいたのは{0}です。",
"1yc8yfn": "飛行画面でスティックの間にある重さスライダーが、まさにこの悩み用です。クアッドが運ぶ重さを変えるので、スロットルを切ると浮かずに落ちます。今は{0}パーセント。右へ動かすほど、スロットルを切ったときに早く落ち、短いパンチの後も浮き上がりにくくなります。ホバー位置もスティックの上へ移り、ストックの{1}パーセントから{3}で{2}になります。私たちを待つ前に動かしてみる価値あり。それで飛んだラップは、名前の横に重さを付けて公開ボードに載ります。",
"r74boy": "このクアッドはスロットル制限なしだとスティックの{0}パーセントでホバーするので、ストロークのほとんどがホバーより上です。レート、スロットル制限、75パーセントにするとホバーが{1}パーセントに移り、屋内で使える上昇力を失わずに細かい操作が戻ります。私たちを待つ前に試す価値あり。",
"1xpffsm": "飛行感のチューニングをオンにする",
"194uxup": "飛行感のチューニングはオンです。着地中は、スティックの間、重さの横に{0}{1}。ストックより良い設定があれば、フライトの最後に送るかどうか聞かれます。",
"1elhpti": "自分で変えてみたい？飛行感のチューニングをオンにすると、地面にいる間、重さの横に{0}が出ます：{1}。ストックより良い設定があれば、フライト後に数字を送れます。自分でオンにしないかぎりオフで、「はい」がなければ何も送信されません。",
