"1vcax0y": "この結果を送る",
"13gi980": "チューンを送る",
"pve1j9": "{0}。{2}で{1}飛行。これらはあなたの言葉と一緒にボードへ送られ、機体と物理バージョンごとにまとめられて、シムをチューンしている人たちがパイロットの好みを見られるようになります。あなたのチューン、レート、飛行感レポートと同じ詳細も一緒に送られます。",
