"6zlbxk": "カード：5インチレース、フープレース、フリースタイル、ビルダー。気が変わったらここからやり直せます。",
"1wxmu24": "センター、フルレンジ、そしてスティックごとに名前の付いた動きをひとつ。実際に動いた軸を割り当てるので、シムが間違ったチャンネルで読んでいるスティックはこれで直ります。どのバーも動かないスティックは直りません。上のブロックがどこで失われているかを示します。",
