"1llq124": "公開されたマップ",
"jj3lyh": "ボードのマップ",
"wuzuho": "「新着」は最後に公開されたものが先頭。「高評価」はパイロットが付けた星で人気のものが先頭で、だれも評価していないマップは最後になります。",
"dylcn7": "このマップを評価",
