"4uqxss": "地面で裏返しになると、TURTLE MODEの表示が出ます。右のパッドでピッチかロールを入れると起き上がります。タイミングを合わせる必要はありません。指を離してから離陸します。",
"1qyunph": "右上のポーズチップ。当たると跳ね返ります。ペナルティは時間です。再開して、裏返しならピッチかロールを入れます。",
