"lkidd0": "左スティック（モード{0}）",
"dgt1q3": "{0}。モードはプロポで設定します。このページは設定でそれに合わせます。",
"1a3en5u": "このページを読み込む前にプロポをジョイスティックモードにしてから、設定でスティックのキャリブレーションを実行してください。",
"8pq8oh": "ピッチでカーソルを動かし、ロール右で決定、ロール左で戻ります。ポーズやゴールのあとは、スティックを離して少し待ち、ロールを一拍保ってください。",
"d45qj0": "リスタート",
"ezjsbi": "キーボードのR、またはプロポのスイッチ：設定、リスタートスイッチで、スイッチを倒します。",
"o7cl2g": "手を離すと、そのときの姿勢を保ちます。曲がったら、必ず自分で戻す必要があります。",
"etorb5": "地面で裏返しになると、TURTLE MODEの表示が出ます。右スティックでピッチかロールを入れると起き上がります。タイミングを合わせる必要はありません。スティックを中央に戻してから離陸します。",
"1ri6cg": "これは何か",
