"14cfpm3": "角度を決める",
"11n5q78": "スロットルはアイドル。OSDが30から40度くらいを示すまで前に傾けます。スティックを中央へ。モーターがその角度を保ちます。",
"1aa3oyb": "スロットルを約20パーセントより上にパンチします。保持が解け、プロペラが空気をつかみ、飛び出します。発進後はもう一度Lでリセットされます。",
"14arqvb": "上矢印がピッチ前。Wがスロットル。ローンチコントロールは保持の間だけアクロに切り替え、発進後は自分のモードに戻ります。",
"r89zwp": "本物の基板と同じ手順です。Lがモードスイッチ。launch_angle_limit と launch_trigger_throttle_percent は、クアッドの中のファームウェアベンチで細かく調整できます。",
"1wrrqt3": "スタート位置で倒れると、TURTLE MODEに切り替わります。ピッチかロールで起こします。タイミングを合わせる必要はありません。スティックを中央に戻し、Lを押してもう一度発進します。",
"1x7j2uc": "ローンチコントロール（クアッドでオンにした場合）。傾けて、中央、パンチ。",
"1xmpyfk": "飛行中にアングルとアクロを切り替え、その選択を保ちます。",
"1eyul69": "R、そしてEscape",
"1ns2uml": "スタートラインに戻って、ポーズ。",
"1hg0wdz": "地面で裏返しになると、TURTLE MODEの表示が出ます。矢印キーでピッチかロールを入れると起き上がります。タイミングを合わせる必要はありません。キーを離してから離陸します。",
"19jaz7h": "バグ報告やフィードバック。空中にいるときはポーズしてから、フォームを開きます。",
"1ogqofk": "パッドは飛行中、親指の下に現れます。",
"1harh8g": "スティックを動かしてください。プロポに合わせて動きます。",
"149s8uu": "Lで準備。傾けて、中央、パンチ。ジンバルは手の動きに合わせたままです。",
"rt9bay": "キーを押してください。手の動きに合わせて動きます。",
"utog3i": "親指スティックは本物の比例スティックなので、クアッドで設定したフライトモードで飛びます。初期設定はプロポと同じアクロです。アングルは覚えるあいだやさしく、右のパッドを離すとクアッドが自分で水平に戻ります。",
"1uqyqut": "プロポは初期設定でアクロで飛びます。スティックは回転の速さを指示し、離すとゼロを指示するので、クアッドはそのときの姿勢を保ちます。クアッドのフライトモードか、飛行中のMで変えられます。",
"wtsp1v": "初期設定はオフです。保持からのパンチは激しく、だれもが望むわけではないからです。クアッドでオンにして、パッドの上でL。緑のLAUNCH表示がピッチ角です。スロットルが発進に近づくと点滅します。",
"t0ww0i": "キーはオンかオフなので、押す長さがアナログの代わりです。軽く押すとスティックが少し動き、押し続けると飛びやすい量で止まり、長く押すとフルになります。キーでのレースはアングルで始まるので、離すとクアッドが水平に戻ります。",
