"1lrz4zo": "ガラスの上の親指はジンバルの4分の1ほどしか動かせず、中央に戻す力もないので、下の数字はプロポの初期値よりおだやかにしてあります。ロール、ピッチ、ヨーは指を離すと戻り、スロットルはプロポと同じく、離した場所にとどまります。",
"iulg1q": "キーはスティックではありません。押し続けるとスティックは34パーセントまで上がり、約0.75秒まではそこにとどまり、1.25秒でフルまで伸びます。つまり下のレートはプロポで飛ぶときのレートで、軽く押しただけではその3分の1ほどにしかなりません。キーボードでの飛行が数字より固く、効きが遅く感じるのはそのためです。ゲームパッドやUSBジョイスティックモードのプロポならカーブ全体が使えます。また、キーでのレースはアングルで始まり、アングルはこのカーブを無視します。クアッドのキーボードレース、または飛行中のMでアクロになります。",
"j83vdk": "プロポからの信号を待っています。スティックを動かしてください。",
