"tn3t15": "これはフレームレートと同じ毎秒{0}回で、このブラウザーが描画フレームごとに1回しかプロポを読んでいないということです。フィードフォワードはフレーム間の変化に働くので、1フレームに1段ずつ動くスティックは、押し込みではなく小刻みな突きの連続として感じられます。下のレートでは直せません。",
"1iahfwq": "このプロポはスティックの全ストロークを約{0}段階で送っていて、高いレートでは粗さを感じるほどです。USBの刻みが細かいプロポか、低めのレートでやわらぎます。",
