"yajn08": "{0}インチコース",
"1e05oqz": "空のフィールドでビルダーを開きます。キャンバスにあったものは読み込みリストに残ります。作ったコースはこのブラウザーに保存されます。消去したり別のデバイスを使ったりすると、何もない状態から始まります。コースを公開すると公開ボードに載ります。",
