"3sm2ze": "強め",
"1xnvdto": "フルサイズのフリースタイル兼レース用クアッド: パワーのわりに軽く、とても速く、それを活かせる広いフィールド。機体ごとにチューン、PID、バッテリー、重量、カメラを別々に持ちます。機体を替えると、その機体の設定が前のまま戻り (初回は標準設定)、ビルダーも屋外フィールドとリビングで切り替わります。自分のレートは、標準のままでなければ一緒に付いてきます。",
"53x6f3": "ボードやほかのパイロットからの共有コードを貼り付けます。まず中身を確認でき、自分のに戻すこともできます。",
"9ww08a": "マスター倍率",
