"1roremq": "ダイナミックダンピング、D max",
"1e0pboe": "スティックレスポンス、FF",
"we45r2": "ピッチの追従",
"1dlny13": "ピッチのダンピング",
"1b1bac5": "下のすべてはこのチューンのもので、チューンごとに調整を別々に持ちます。",
"193v7i": "すべてを一度に: P、I、D、フィードフォワードが比率を保ったまま一緒に変わります。これは「もっと硬くする」つまみで、飛行フィールへのフィードバックで求められていたものです。標準は{0}。以前ここにあった硬めのプリセットは{1}で、フィードバックが求めていたのはそのくらいの幅です。",
"c3fbrt": "スティックが求めるレートをクアッドがどれだけ強く追うか。低いとゆったり滑らか、高いと目標値にピタッと合って保ちます。",
"amoq3u": "ゆっくりした誤差の項だけ。低すぎると大きな動きで姿勢がずれていき、高すぎると長いスティック操作の間にたまって、スティックを戻したときにピクッと吐き出します。この機体モデルでは、ずれより先にピクつきが出ます。",
"1kt9nne": "回転に抵抗し、止まりを滑らかにし、プロップウォッシュを抑えます。実機ではDの代償はモーターの熱とジャイロノイズですが、このモデルのジャイロはきれいなので、ダンピングはほぼタダで、硬めのチューンは高く設定します。",
"1wqluz6": "速い動きや止まりのとき、基本のDにどれだけDが上乗せされるか。ゼロならDは一定です。",
"10nibr2": "フィードフォワードは、誤差が出る前に、スティックの動きそのものに反応して押します。高いと即座に反応し、高すぎると動き出しのたびに行きすぎます。ゼロならPとDだけで飛びます。",
"i42c2o": "ロールに対するピッチのPとI。クアッドは幅より前後が長いので、たいていピッチが数パーセント多めです。",
"1a9uio": "ロールに対するピッチのD。ピッチの追従があるのと同じ理由です。",
