"bw3a2g": "下の数値に名前を付けて保存すると、ワンプッシュで戻せます。2つ目のコースで欲しくなる機能です。プリセットはこのデバイスのこのブラウザーにだけ保存されます。サイトデータの消去、プライベートウィンドウ、別のブラウザー、別のデバイスでは何もない状態から始まります。アカウントはなく、何もアップロードされません。",
"g0jyc7": "小さなスティック操作にクアッドがどれだけ速く応えるか。カーブの中央での傾きです。",
