"19jtx1c": "4枚の羽根が回る塔型の風車で、正面から見て反時計回りです。羽根にも塔にも当たり判定があります: 2枚の羽根の間をタイミングよく抜けるか、羽根と塔の間を飛ぼう。速度は1分あたりの回転数で、0ならローターで決めた位置で止まります。向きは東西南北の4方向だけです。物理が追える面で羽根を回すためです。",
