"1ua7ifj": "ルーラーは3Dで、斜めからでも上からでも測れます。Vキーかバーの3Dを押してください。",
"15onv1j": "ツールの下で文字を選び、{0}をクリックします。文字のすき間はそれぞれ通り抜けるゲートです: Wには2つのVの間に1つ、Bには2つあります。",
"r5y8ck": "クリックして道路のノードを置きます: 車が走れるようにノードを通って曲がります。最初のノードをクリックするとループが閉じ、Enterかダブルクリックで開いたまま完成、Escapeで中止です。",
