"tvaqrx": "道路には{0}個のノードが必要です: 次に進む場所をクリックしてください。",
"1xk4hcq": "道路を敷きました。ノードをドラッグすると形を変えられ、2つのノードの間のつまみをドラッグするとノードが増え、ノードをクリックしてDeleteで取り除けます。車両を選んで道路をクリックすると車を置けます。",
"ogb731": "道路には2つのノードが必要です。代わりに道路そのものを削除してください: ノードから離れた場所をクリックしてDeleteを押します。",
"1xp7uwj": "2つのノードではループを閉じられないので、道路は開いた状態になりました。",
"1hudr1b": "車両は道路の上に置きます: 道路の上か、すぐ横をクリックしてください。",
"1vqxq39": "マップのスタートパッドはパイロットが始まる1セットだけなので、今あったものを動かしました。",
"b9600b": "コースのスタートパッドは1セットだけなので、今あったものを動かしました。",
"1wr6pa0": "穴はそれぞれ独立したゲートです。このスタックは上向きのスパイラルです: 下、回り込み、そして上。{0}で変更できます。",
"co4ov2": "セクションはふつうのピースの集まりで、置いた順に飛びます。ほかのピースと同じように動かす、回す、大きさを変えるか、元に戻すを押して別の形で置き直してください。",
"n9k3yi": "見えないゲートは、ほかのゲートと同じようにスコアになり点灯しますが、まわりに何も作られません。部屋の中では次のゲートである間だけ点灯します。ゲートと同じように大きさを変え、回し、飛べます。カードのフレームでパイプを戻せます。",
"142x321": "角度はラップがハードルの上を飛ぶラインに対するものなので、先にハードルを飛ぶ必要があります: 上を飛ぶでラップがそこを通ります。",
"1tt8aac": "ウォールは支柱を共有するゲートを1つにまとめたものです。区画ごとに別々の通過になり、ウィーブで飛びます: カードにどちら向きかが出ていて、変更もできます。",
"1fnwagm": "そのゲートは{0}になりました。場所も飛ぶ順番も同じです。カードの文字で別の文字に変えられ、ゲートにするで元に戻せます。",
