"k5t9kx": "スタックの3つ目のゲート",
"7o057k": "ポール",
"q4xm7t": "ゲートの中心から少なくとも{0}、ほかのポールから{1}離します。",
"15ug81": "ゲートの向き",
"ws7hxd": "すべてのゲートはコースの2つの軸のどちらかに沿って向きます: どの2つのゲートの間の角度も90度の倍数です。まっすぐなパイプと直角の継手のキットでは、斜めのコースは作れません。",
"1xr7c94": "収まる範囲",
