"n0pzsc": "長く広いカーブ: ゲートは、パイロットがスピードを保ったまま抜けられる弧に沿って置かれます。",
"tpfya4": "折り返すターン: ゲートは半円に沿って広がり、最後のゲートは最初のゲートが来た方向を向きます。ゲート2つならヘアピンペアです。",
"zmh3r4": "シケイン",
"15pzf1": "片側へすばやく振って反対へ戻り、そのままラインに沿って進む: ゲートはラインから外れて戻ります。",
