"hx2nwi": "一列のゲートが、前のゲートより一段ずつ高く、または低くなります: 上るか下る階段です。",
"ujrhgf": "フラッグスラローム",
"1lk6huk": "一列のフラッグを、ラップが左右交互に通ります。最初にどちら側を通るかは選べます。フラッグは回って飛ぶもので、上は越えません。",
"fg5qgx": "Dutch 8",
