"1h88uzq": "各辺はそれぞれ別のパイプです: 上のバーはいちばん上の開口の上、下のバーはいちばん下の開口の下にあり、支柱は開口ごとに1区間です。左と右のボタンは支柱全体を、その下のボタンは開口1つ分の区間を外します。外しても開口は判定されます。3Dビューでは、選択中のゲートのパイプをクリックしてDeleteを押すと、クリックした区間だけが外れます。左右は、上辺のフラッグと同じく、ゲートに向かって見た向きです。",
"3wzvo0": "各辺はそれぞれ別のパイプです。1本外しても開口は判定されて光り、そこに当たるパイプはありません。3Dビューでは、選択中のゲートのパイプをクリックしてDeleteを押します。左右は、上辺のフラッグと同じく、ゲートに向かって見た向きです。",
