"17wx66j": "ゲートに向かって見たときの、上辺でペナントが立つ位置。「上」にすると、板の中央、開口の真上にマストが1本立ちます。マストの高さは下の寸法にあるフラッグの高さで、マストには当たり判定があります: 上のレールへダイブするパイロットが当たることがあります。",
