"3eggiu": ": RaceGOW、部屋で飛ばす65 mmフープ用。ゲートは24から28インチ、隣り合うゲートは中心間30インチ、コース全体は最小ゲートで4 x 6フィートに収まり、ゲートに合わせて拡大されます。すべてのピースは部屋の中央からインチで測り、グリッドは1インチです。",
"1329h41": ": フィールドで飛ばす5インチクアッド。MultiGPのゲートサイズで、すべてのピースはフィールドの角からメートルで測ります。",
