"trp2du": "ラインはラップの{0} m地点で地面の下に潜ります。",
"63njfk": "{0}と{1}は{2} mしか離れておらず、飛行順で続いているので、1回の通過で両方に届きます。レースは、さらに{4} m飛んでからでないと{3}を数えません。その間に1周するつもりなら、片方を離してください。",
"1l1fncv": "{0}は{1}に背を向けて終わるので、ラインは折り返さないと届きません。{2}を図形の終わる位置に置くか、図形を逆向きにしてください。",
"1ozh84i": "{0}は後ろ向きに出て{1}に入るので、ラインは折り返さないと始められません。{2}を逆向きにするか、図形を動かしてください。",
"1emgxmg": "{0}は{1}の方へ戻る向きで始まるので、ラインは折り返さないと始められません。{2}を図形の始まる位置に置くか、図形を逆向きにしてください。",
"laqehz": "ラインはラップの{1} m地点で{0}の上を越えます。フラッグのラインは上へどこまでも伸びるので、周りを回って飛び、上は越えません: ラインをどちらかの側へ動かしてください。",
"1xr491b": "{0}は{2}に対して直角から{1}度ずれています。すべてのゲートはコースの2つの軸のどちらかに沿って向きます: ほかのゲートと直角になるように回してください。",
"1tgybl6": "{0}の開口は{1}です。RaceGOWのゲートは28インチ四方に収まります。",
"1rlgckd": "{0}の開口は{1}です。RaceGOWの最小ゲートは24インチです。",
"6we35z": "{0}のいちばん下の開口は中心が{1}にあります。地面のゲートは中心が20インチ以下です。",
"1d69zcl": "{0}の2つ目の開口は中心が{1}にあります。2段重ねの上のゲートは少なくとも42インチの高さが必要です。",
"xv7gqv": "{0}の3つ目の開口は中心が{1}にあります。3つ目のゲートは少なくとも69インチの高さが必要です。",
"1imcxyb": "{0}は{1}まで届き、{2} mの天井を突き抜けます。RaceGOWのコースは屋内で飛びます。",
"19w4clv": "{0}は開口を{1}間隔で重ねています。隣り合うゲートは、重ねでも横並びでも、中心間27から33インチです。",
"1ims1cr": "{0}と{1}は{2}離れています。これだけ近い2つのゲートは隣り合うゲートで、隣り合うゲートは中心間27から33インチです。",
"8wy7kh": "{0}と{1}は{2}離れています。横並びのペアのつもりなら、隣り合うゲートは中心間27から33インチで、標準は30です。",
"107lerp": "{0}は{2}から{1}の位置にあります。ポールはゲートの中心から少なくとも14インチ離します。",
"1uyg16": "{0}と{1}は{2}離れています。ポール同士は少なくとも36インチ離します。",
"zolwjx": "コースは{0} x {1} mに広がっています。RaceGOWのコースは、このゲートサイズで{2} x {3} mに収まります。",
"4hr5zo": "Sを押して、スタートさせたい場所をクリックしてください。",
"lk5z4a": "列は2つの高さにもまたがっています: マット{0}は{1} m、機体のマットは{2} mにあるため、マットは{3} mに描かれ、浮いたり埋まったりするものがあります。列を1つの面の上に動かしてください。",
"ls6ln3": "スタートパッドが2つの高さにまたがっています: マット{0}は{1} m、機体のマットは{2} mにあります。マットは{3} mに描かれるので、浮いたり埋まったりするものがあります。列を1つの面の上に動かしてください。",
"1hy0328": "{0}が{1}にめり込んでいます: 片方がもう片方を突き抜けて建っています。どちらかを動かしてください。",
"500wke": "{0}と{1}の間に{2} mのすき間があります。5インチが通るには{3} m必要なので、ふさぐか広げてください。",
"10fprle": "{0}の羽根が回ると{1}を突き抜けます。どちらかを動かすか、風車の向きを変えてください。",
"h9gzex": "{0}は飛びません: マップで飛ぶバルーンチェイスは1つだけで、それは{1}です。どちらかを削除してください。",
"ym814r": "{0}のウィンドウを{1}がふさいでいるので、きれいに飛び抜けられません。ギャップか、中にあるものを動かしてください。",
"1l0co51": "名前付きギャップ",
"d008ky": "{0}は敷地の外に立っています。",
"g0m2mr": "{0}は敷地の端からはみ出しています。",
"np34nj": "{0}は完全に地面の下に沈んでいるので、何も見えず、当たり判定もありません。ベースを上げて地上に出してください。",
"2cz3wz": "このマップには当たり判定が{0}個あり、遅いマシンでもなめらかに読み込んで飛べるようにマップで抑えている{1}個を超えています。いちばん多いのは{2}で、{3}個です。",
"1o9p6b3": "{0}の周りでは、物理が機体に対して調べる形状が{1}個になりますが、調べるのは最大{2}個です: 残りは外され、そこでは機体がすり抜けることがあります。これらのエレメントの間隔を広げるか、数を減らしてください。",
"36jvfa": "{0}には道路がありません: {1}。駐車したままで、敷地の南の端に沿った列に描かれます。道路の上にドラッグするか、削除してください。",
"58628i": "{0}は敷地の端からはみ出しています。",
"kof9h3": "{0}は{1}を突き抜けています: この道路の車はそこに突っ込みます。車が通れる余裕ができるまで、道路か{2}を動かしてください。",
"1x8yhyt": "{0}はスタートパッドの上を通っているので、この道路の車は発進を待つ機体を突き抜けます。道路かパッドを動かしてください。",
"11r26o9": "{0}は機体のスタート位置から1メートル以内を通るので、この道路の車は、パッドを離れる前の機体に接触します。道路かパッドを動かしてください。",
"e5birv": "{0}は、スタートパッドがないときにパイロットがスタートする場所を通っているので、この道路の車は機体を突き抜けます。道路を動かすか、Sを押してスタートパッドを道路から離して置いてください。",
"5s8foe": "{0}と{1}はどちらも開いた道路の{2}にいます: どの車も中央を走って端まで行って戻るので、2台は正面から出会ってすり抜け合います。道路を閉じてループにするか、車を1台だけにしてください。",
"1c7ews2": "{0}と{1}は{2}の1車線を逆向きに走るので、正面から出会ってすり抜け合います。道路を2車線にするか、片方の向きを変えてください。",
"b92v0l": "同じ最高速度と同じドリフトにするか、片方をリバースにして反対車線を走らせてください。",
"1t8095q": "同じ最高速度と同じドリフトにするか、道路を2車線にして片方をリバースにしてください。",
"ntbmqa": "{0}は{1}に重なってスタートします。どちらかを道路に沿ってスライドさせてください。",
